/*
 * Program: EECS 348 Assignment 6 - Sudoku Solver
 * Description: Solves Sudoku puzzles with recursive, object-oriented
 *              backtracking and writes every solution to one output file.
 * Inputs: puzzle1.txt - puzzle5.txt (9 rows, digits or "_" for blank)
 * Outputs: solutions.txt; for each puzzle it contains "Puzzle: <file>",
 *          then all solutions plus "Solutions found: n", or exactly
 *          "No solution found." if there are none.
 * Collaborators: ChatGPT and Gemini (source code generated by both tools);
 *                Claude (Anthropic) for review, guidance, and the
 *                Assignment 6 modifications;
 * Other sources: ChatGPT, Gemini, Claude
 * Original author: Josselyn Bui
 * Creation date: 10/15/2026
 * Revised by: Dalton Brockert
 * Revision date: 10/29/2026
 * Revised by: Josselyn Bui
 * Revision date: 11/12/2026
 *
 * Inherited code: SudokuSolver class structure, recursive backtracking
 *                 approach, bitmask validity checks, and file loading.
 * Modified code for assignment 6: long long solution counter, one-time blank-cell list
 *                replacing the per-call board scan, and a bitmask loop
 *                over only the legal digits.
 */

#include <iostream>   // cout and cerr, used for status and error messages
#include <fstream>    // ifstream and ofstream, used for file input and output
#include <vector>     // holds the five input file names
#include <string>     // stores file names and input symbols
#include <cstddef>    // std::size_t for the loop index in main

// ---------------------------------------------------------------------
// Block: SudokuSolver class
// Original class structure retained from Josselyn Bui's Assignment 4.
// Revisions are marked "MODIFIED BY JOSSELYN FOR ASSIGNMENT 6" below.
// ---------------------------------------------------------------------
class SudokuSolver {
private:
    int grid[9][9];             // the board; 0 means the cell is empty
    long long solutionCount;    // MODIFIED BY JOSSELYN FOR ASSIGNMENT 6: was int, now long long to avoid overflow
    int rowMask[9];             // bit d is set if digit d is used in that row
    int colMask[9];             // bit d is set if digit d is used in that column
    int boxMask[9];             // bit d is set if digit d is used in that 3x3 box

    // MODIFIED BY JOSSELYN FOR ASSIGNMENT 6: new blank-cell list members
    unsigned char blanks[81];   // position (0-80) of each blank cell, row-major order
    int blankCount;             // how many blank cells are in the list
    // MODIFIED BY JOSSELYN FOR ASSIGNMENT 6

    // Resets all three bitmask arrays to "no digits used".
    void clearMasks() {
        for (int i = 0; i < 9; ++i) {   // visit each row, column, and box slot
            rowMask[i] = 0;             // no digits used in this row
            colMask[i] = 0;             // no digits used in this column
            boxMask[i] = 0;             // no digits used in this box
        }
    }

    // O(1) validity check using the bitmasks instead of scanning 27 cells.
    // Box index is (row / 3) * 3 + (col / 3).
    bool isValid(int row, int col, int num) const {
        int used = rowMask[row] | colMask[col]
                 | boxMask[(row / 3) * 3 + (col / 3)];  // all digits blocked for this cell
        return (used & (1 << num)) == 0;                // valid if bit for num is clear
    }

    // Puts a digit on the board and records it in the bitmasks.
    void placeDigit(int row, int col, int num) {
        int bit = 1 << num;                      // bit that represents this digit
        grid[row][col] = num;                    // write the digit into the board
        rowMask[row] |= bit;                     // mark digit used in the row
        colMask[col] |= bit;                     // mark digit used in the column
        boxMask[(row / 3) * 3 + (col / 3)] |= bit;  // mark digit used in the box
    }

    // Removes the digit from a cell and clears it from the bitmasks.
    void removeDigit(int row, int col) {
        int bit = 1 << grid[row][col];           // bit of the digit being removed
        grid[row][col] = 0;                      // empty the cell
        rowMask[row] &= ~bit;                    // digit no longer used in the row
        colMask[col] &= ~bit;                    // digit no longer used in the column
        boxMask[(row / 3) * 3 + (col / 3)] &= ~bit;  // digit no longer used in the box
    }

    // Checks the original clues for duplicates AND builds the bitmasks
    // from them. Returns false if two clues conflict.
    bool cluesConsistent() {
        clearMasks();                            // start from a clean mask state
        for (int r = 0; r < 9; ++r) {            // go through every row
            for (int c = 0; c < 9; ++c) {        // go through every column
                int digit = grid[r][c];          // clue (or 0 if blank)
                if (digit == 0) {                // blank cells have nothing to check
                    continue;
                }
                if (!isValid(r, c, digit)) {     // digit already used in row/col/box
                    return false;                // duplicate clue means no solution
                }
                placeDigit(r, c, digit);         // record the clue in the masks
            }
        }
        return true;                             // all clues are consistent
    }

    // MODIFIED BY JOSSELYN FOR ASSIGNMENT 6: findNextEmpty() was removed
    // from this spot, and buildBlankList() replaces it. It scans the board once
    // and records where each blank cell is, so the recursion walks this list by
    // index instead of rescanning the board on every call. Cells are listed in
    // row-major order, so the solutions print in the same order as before.
    void buildBlankList() {
        blankCount = 0;                           // start with an empty list
        for (int pos = 0; pos < 81; ++pos) {      // visit cells in row-major order
            if (grid[pos / 9][pos % 9] == 0) {    // pos / 9 is the row, pos % 9 is the column
                blanks[blankCount] = static_cast<unsigned char>(pos);  // remember this blank
                ++blankCount;                     // one more blank in the list
            }
        }
    }
    // MODIFIED BY JOSSELYN FOR ASSIGNMENT 6

    // Writes each completed grid directly to the selected output stream.
    // No solution labels are written, so each grid retains input-file format.
    void printGrid(std::ostream &out) const {
        for (int r = 0; r < 9; ++r) {            // each row
            for (int c = 0; c < 9; ++c) {        // each column
                if (grid[r][c] == 0) {
                    out << "_";                  // blank cell
                } else {
                    out << grid[r][c];           // digit
                }
                if (c < 8) {
                    out << " ";                  // space between cells
                }
            }
            out << "\n";                         // end of row
        }
    }

    // Recursive backtracking that outputs every solution.
    // MODIFIED BY JOSSELYN FOR ASSIGNMENT 6: idx is now the position in
    // the blank list (not a board cell), and the digit loop walks only the
    // legal digits using a bitmask.
    void solveRecursive(std::ostream &out, int idx) {
        if (idx == blankCount) {                 // no blanks left, so the board is full
            ++solutionCount;                     // one more solution found
            printGrid(out);                      // write it to the file
            return;                              // continue searching other branches
        }

        int pos = blanks[idx];                   // board position of this blank (0-80)
        int row = pos / 9;                       // row of this blank
        int col = pos % 9;                       // column of this blank
        int boxIdx = (row / 3) * 3 + (col / 3);  // which 3x3 box holds the cell

        // Digits blocked by row, column, or box are OR-ed together, inverted,
        // then masked with 0x3FE (bits 1 to 9) so bit d means "digit d is legal".
        int available = ~(rowMask[row] | colMask[col] | boxMask[boxIdx]) & 0x3FE;

        while (available != 0) {                 // loop only over legal digits
            int lowest = available & -available; // isolate the smallest legal digit's bit
            int val = __builtin_ctz(lowest);     // count trailing zeros turns the bit into the digit
            placeDigit(row, col, val);           // place it and update the masks
            solveRecursive(out, idx + 1);        // move on to the next blank in the list
            removeDigit(row, col);               // backtrack and update the masks
            available &= available - 1;          // clear the lowest set bit so the next digit is next
        }
    }
    // MODIFIED BY JOSSELYN FOR ASSIGNMENT 6

public:
    // Constructor: initializes an empty board and zero solutions.
    // MODIFIED BY JOSSELYN FOR ASSIGNMENT 6: blankCount now starts at 0 too
    SudokuSolver() : solutionCount(0), blankCount(0) {
        for (int r = 0; r < 9; ++r) {
            for (int c = 0; c < 9; ++c) {
                grid[r][c] = 0;                  // every cell starts empty
            }
        }
        clearMasks();                            // no digits used yet
    }

    // Reads exactly 81 valid tokens and rejects extra tokens, invalid symbols,
    // incomplete grids, or unreadable files. The board is reset before loading.
    bool loadFromFile(const std::string &filename) {
        std::ifstream inFile(filename.c_str());  // open the puzzle file
        if (!inFile.is_open()) {
            return false;                        // missing or unreadable file
        }

        for (int r = 0; r < 9; ++r) {
            for (int c = 0; c < 9; ++c) {
                grid[r][c] = 0;                  // reset the board
            }
        }
        clearMasks();                            // reset masks with the board
        solutionCount = 0;                       // reset the solution counter

        for (int r = 0; r < 9; ++r) {
            for (int c = 0; c < 9; ++c) {
                std::string token;               // one cell symbol
                if (!(inFile >> token)) {
                    return false;                // fewer than 81 cells
                }

                if (token == "_") {
                    grid[r][c] = 0;              // blank cell
                } else if (token.size() == 1 &&
                           token[0] >= '1' && token[0] <= '9') {
                    grid[r][c] = token[0] - '0'; // clue digit
                } else {
                    return false;                // invalid cell token
                }
            }
        }

        std::string extraToken;                  // reject trailing tokens
        if (inFile >> extraToken) {
            return false;                        // more than 81 cells
        }
        if (inFile.bad()) {
            return false;                        // read error
        }

        return true;                             // puzzle loaded correctly
    }

    // Prints the original puzzle to the console.
    void printGrid() const {
        printGrid(std::cout);
    }

    // Finds every solution and writes the results to the output stream.
    bool solveToFile(std::ostream &out) {
        solutionCount = 0;                       // start counting from zero

        if (!cluesConsistent()) {                // conflicting clues: no solution
            out << "No solution found.\n";
            return static_cast<bool>(out);
        }

        // MODIFIED BY JOSSELYN FOR ASSIGNMENT 6: list the blanks once,
        // after the clues pass the check, then start at index 0 of that list.
        buildBlankList();
        solveRecursive(out, 0);
        // MODIFIED BY JOSSELYN FOR ASSIGNMENT 6

        if (solutionCount == 0) {
            out << "No solution found.\n";       // search found nothing
        } else {
            out << "Solutions found: " << solutionCount << "\n";  // final count
        }

        return static_cast<bool>(out);           // false if writing failed
    }

    // Original compatibility method.
    void solve() {
        solveToFile(std::cout);
    }
};

// Main function processes all five Sudoku puzzles.
int main() {
    const std::vector<std::string> puzzleFiles = {
        "puzzle1.txt",
        "puzzle2.txt",
        "puzzle3.txt",
        "puzzle4.txt",
        "puzzle5.txt"
    };

    std::ofstream outFile("solutions.txt");      // open the single output file once
    if (!outFile.is_open()) {                    // cannot continue without it
        std::cerr << "Error: Could not create solutions.txt\n";
        return 1;
    }

    for (std::size_t i = 0; i < puzzleFiles.size(); ++i) {
        const std::string &filename = puzzleFiles[i];   // current puzzle file

        std::cout << "========================================\n";
        std::cout << filename << " -> solutions.txt\n";
        std::cout << "========================================\n";

        outFile << "Puzzle: " << filename << "\n";       // required header line

        SudokuSolver solver;                     // fresh solver for each puzzle

        if (!solver.loadFromFile(filename)) {
            std::cerr << "Error: Missing, unreadable, or malformed input: "
                      << filename << "\n";

            outFile << "No solution found.\n";   // report and move to the next puzzle
            continue;                            // do not close the shared file
        }

        std::cout << "Original Puzzle:\n";
        solver.printGrid();                      // show the clues on the console

        std::cout << "\nSolving; results are being written to "
                  << "solutions.txt...\n";

        if (!solver.solveToFile(outFile)) {      // search and write all solutions
            std::cerr << "Error: Failed while writing solutions.txt\n";
        }

        std::cout << "\n";
    }

    outFile.close();                             // close once after all puzzles
    if (outFile.fail()) {
        std::cerr << "Error: Failed to finish writing solutions.txt\n";
    }

    return 0;
}